import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long w = Long.parseLong(next());
        long[] cards = new long[(int) n];
        for (int i = 0; i < cards.length; i++) cards[i] = Long.parseLong(next());

        Arrays.sort(cards);
        boolean ok = (n % w == 0);
        if (ok) {
            int count = (int) n;
            long[] values = new long[count];
            long[] counts = new long[count];
            int u = 0;
            for (int i = 0; i < count; i++) {
                if (u > 0 && values[u - 1] == cards[i]) counts[u - 1]++;
                else {
                    values[u] = cards[i];
                    counts[u] = 1;
                    u++;
                }
            }
            long[] expire = new long[u + (int) w + 2];
            long running = 0;
            for (int i = 0; i < u && ok; i++) {
                running -= expire[i];
                if (running > 0 && values[i] != values[i - 1] + 1) ok = false;
                else if (counts[i] < running) ok = false;
                else {
                    expire[i + (int) w] += counts[i] - running;
                    running = counts[i];
                }
            }
            if (ok && running != expire[u]) ok = false;
        }
        System.out.println(ok ? "YES" : "NO");
    }
}
